<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {hostBytes} from './hostBilling'
const props=defineProps<{user:Record<string,any>,api:(p:string,m?:string,b?:any)=>Promise<any>}>(),emit=defineEmits<{close:[],changed:[]}>()
const rows=ref<Record<string,any>[]>([]),nodes=ref<Record<string,any>[]>([]),clients=ref<Record<string,any>[]>([]),draft=ref<Record<string,any>|null>(null),busy=ref(false),error=ref(''),notice=ref(''),link=ref('')
let alive=true,timer:ReturnType<typeof setTimeout>
const base='proxy-users/'+props.user.id+'/devices'
async function load(){const [d,c,n]=await Promise.all([props.api(base),props.api('client-catalog'),props.api('client-policies/nodes?user_id='+props.user.id)]);if(alive){rows.value=d;clients.value=c;nodes.value=n.filter((v:Record<string,any>,i:number,a:Record<string,any>[])=>!['shadowsocks','snell'].includes(v.kind)&&a.findIndex(x=>x.id===v.id)===i)}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();await load();emit('changed')}catch(e){error.value=String(e)}finally{busy.value=false}}
function save(){const d=draft.value;if(!d?.id)return;void run(async()=>{await props.api(base+'/'+d.id,'PUT',{name:d.name,client_id:d.client_id,enabled:!!d.enabled,version:d.version,...(d.registration_source==='observed_client'?{}:{all_nodes:d.all_nodes??true,service_ids:d.service_ids??[]})});draft.value=null;notice.value=d.registration_source==='observed_client'?'客户端记录已保存。':'设备权限已保存，等待在线 Agent 应用。'})}
function toggle(d:Record<string,any>){void run(async()=>{await props.api(base+'/'+d.id,'PUT',{name:d.name,client_id:d.client_id,enabled:!d.enabled,version:d.version});link.value='';notice.value=d.registration_source==='observed_client'?(d.enabled?'已停止该记录再次下载订阅；已下载的凭据仍有效。':'客户端记录已启用。'):d.enabled?'设备已停用，同一客户端标识不能重新订阅；连接凭据撤销等待 Agent 同步。':'设备已启用，可使用原用户链接更新订阅。'})}
function remove(d:Record<string,any>){if(!window.confirm(d.registration_source==='observed_client'?'删除此订阅访问记录并释放名额？再次导入可重新登记，已下载凭据不会撤销。':'删除设备 '+d.name+' 的识别记录并撤销其凭据？名额释放后，此客户端可再次自动登记。'))return;void run(async()=>{await props.api(base+'/'+d.id,'DELETE');link.value='';notice.value='设备记录已删除并释放名额，其他设备不受影响。'})}
function share(d:Record<string,any>){void run(async()=>{link.value=(await props.api(base+'/'+d.id+'/link')).url})}
async function copy(){try{await navigator.clipboard.writeText(link.value);notice.value='旧版设备订阅已复制'}catch{notice.value='请手动复制下方链接'}}
function schedule(){timer=setTimeout(async()=>{if(document.visibilityState!=='hidden'&&!busy.value)try{await load()}catch{};if(alive)schedule()},30000)}
onMounted(()=>{void run(async()=>{});schedule()});onUnmounted(()=>{alive=false;clearTimeout(timer);link.value=''})
</script>
<template><div class="modal-backdrop"><section class="modal devices-modal" role="dialog" aria-modal="true" aria-label="用户设备管理"><div class="modal-heading"><div><h2>{{user.name}} · 客户端访问记录</h2><p class="muted">最近记录 {{rows.filter(d=>d.enabled).length}} / {{user.effective_max_devices||'未启用限制'}} · 用户与所属组取最严格的非零设备上限</p></div><button class="secondary" @click="emit('close')">关闭</button></div><div class="form-content"><p class="form-note">把用户的同一个订阅链接导入客户端即可，无须手工登记。兼容模式支持 Clash Verge / FlClash，按来源 IP 和客户端类型识别最近 7 天的订阅访问，超出名额会提示。相同地址与客户端可能合并，换网络可能生成新记录，不能精确代表物理设备或阻止复制凭据。未设设备上限时，最多保留最近 30 条启用的兼容访问记录，停用记录单独保留。</p><p class="form-note">严格 HWID 模式需要客户端自报标识并分配独立身份；系统、型号与 HWID 都是自报信息。普通 Clash 客户端一般不回传型号，页面显示实际收到的客户端名称、来源和更新时间。兼容记录流量归入用户总量，不虚构每台设备的独立流量。</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><button class="secondary" :disabled="busy" @click="run(async()=>{})">刷新已识别设备</button><form v-if="draft" class="device-editor" @submit.prevent="save"><div class="fields"><label>显示名称<input v-model="draft.name" required maxlength="100"></label><label v-if="draft.registration_source!=='observed_client'">客户端格式<select v-model="draft.client_id"><option v-for="c in clients" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label v-else>识别到的客户端<input :value="draft.user_agent||draft.client_id" readonly><small>实际收到的客户端信息，随更新订阅刷新。</small></label></div><label v-if="draft.registration_source!=='observed_client'" class="check-label"><input v-model="draft.all_nodes" type="checkbox">跟随用户组的全部授权入站</label><div v-if="draft.registration_source!=='observed_client'&&!draft.all_nodes" class="choice-list"><label v-for="n in nodes" :key="n.id"><input v-model="draft.service_ids" type="checkbox" :value="n.id">{{n.node_name??n.name}} · {{n.kind}}</label><p class="muted">未选择任何入站时没有连接权限；不会回退为全部。</p></div><div class="row-actions"><button class="primary" :disabled="busy">保存权限</button><button type="button" class="secondary" @click="draft=null">取消</button></div></form><div v-if="link" class="device-link"><label>兼容旧版设备订阅（包含访问凭据）<input :value="link" readonly aria-label="设备专属订阅"></label><button class="secondary" @click="copy">复制链接</button></div><div class="device-grid"><article v-for="d in rows" :key="d.id"><div class="device-title"><h3>{{d.name}}</h3><span :class="['status',d.enabled?'succeeded':'pending']">{{d.enabled?'启用':'停用'}}</span></div><p>{{d.registration_source==='observed_client'?'兼容订阅访问':d.registration_source==='subscription_hwid'?'HWID 自报身份':'旧版独立身份'}} · {{clients.find(c=>c.id===d.client_id)?.name??d.client_id}}</p><dl><dt>系统 / 型号（客户端自报）</dt><dd>{{[d.device_os,d.os_version,d.device_model].filter(Boolean).join(' · ')||'未提供'}}</dd><dt>节点权限</dt><dd>{{d.registration_source==='observed_client'?'跟随用户全部授权':d.all_nodes?'跟随用户全部授权':(d.service_ids?.length??0)+' 个指定入站'}}</dd><dt>客户端自报</dt><dd>{{d.user_agent||'未提供'}}</dd><dt>最近订阅更新</dt><dd>{{d.last_subscription_at?new Date(d.last_subscription_at).toLocaleString():'—'}}</dd><dt>{{d.registration_source==='observed_client'?'同来源代理活动（近似关联）':'最近代理活动'}}</dt><dd>{{d.last_connected_at?new Date(d.last_connected_at).toLocaleString():'尚未观察到'}}</dd><dt>最近来源 IP</dt><dd>{{d.source_ip||'—'}}</dd><dt>原始累计</dt><dd>{{d.registration_source==='observed_client'?'归入用户总量':hostBytes(d.raw_lifetime_bytes)}}</dd></dl><div class="row-actions"><button v-if="d.registration_source!=='subscription_hwid'&&d.registration_source!=='observed_client'" class="text-button" :disabled="busy||!d.enabled" @click="share(d)">旧版订阅</button><button class="text-button" :disabled="busy" @click="draft={...d}">编辑权限</button><button class="text-button" :disabled="busy" @click="toggle(d)">{{d.enabled?'停用':'启用'}}</button><button class="text-button danger" :disabled="busy" @click="remove(d)">删除记录</button></div></article></div><p v-if="!rows.length" class="console-empty">尚未收到客户端订阅请求。客户端更新用户订阅后自动显示，无须在此创建设备。</p></div></section></div></template>
<style scoped>.devices-modal{width:min(1100px,96vw)}.device-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:18px}.device-grid article,.device-editor,.device-link{padding:16px;border:1px solid var(--border);border-radius:12px;min-width:0}.device-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.device-title h3{margin:0;font-size:17px}.device-grid p{font-size:12px;color:var(--muted)}.device-grid dl{font-size:12px;line-height:1.7}.device-grid dt{color:var(--muted);margin-top:8px}.device-grid dd{margin:0;overflow-wrap:anywhere}.device-editor,.device-link{margin-top:16px}.device-link input{width:100%;min-width:0}.device-link button{margin-top:10px}@media(max-width:680px){.device-grid{grid-template-columns:1fr}}</style>
